# PTX source for fp16 GELU (tanh approximation) on NVIDIA A100 (sm_80)
PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry gelu_fp16(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    //=== Registers ==========================================================
    .reg .pred   %p;
    .reg .b32    %tid, %ntid, %ctaid, %tmp;
    .reg .b64    %rd_input, %rd_output, %rd_N;
    .reg .b64    %idx, %addr_in, %addr_out;
    .reg .f16    %h_in, %h_out;
    .reg .f32    %f_x, %f_x3, %f_inner, %f_tanh_arg, %f_tanh, %f_y;
    .reg .f32    %c_044715, %c_sqrt_2_over_pi, %c_half, %c_one;

    //=== Load kernel parameters ==============================================
    ld.param.u64    %rd_input,  [input_ptr];
    ld.param.u64    %rd_output, [output_ptr];
    ld.param.u64    %rd_N,      [N];

    //=== Thread indices ======================================================
    mov.u32         %tid,   %tid.x;
    mov.u32         %ntid,  %ntid.x;
    mov.u32         %ctaid, %ctaid.x;
    mad.lo.u32      %tmp,   %ctaid, %ntid, %tid;   // idx = ctaid*ntid + tid
    cvt.u64.u32     %idx,   %tmp;

    //=== Bounds check ========================================================
    setp.lt.u64     %p, %idx, %rd_N;
    @!%p bra        DONE;

    //=== Compute addresses (byte offsets, half = 2 bytes) =====================
    mul.lo.u64      %addr_in,  %idx, 2;
    add.u64         %addr_in,  %addr_in, %rd_input;

    mul.lo.u64      %addr_out, %idx, 2;
    add.u64         %addr_out, %addr_out, %rd_output;

    //=== Load fp16 input ======================================================
    ld.global.f16   %h_in, [%addr_in];

    //=== Convert to fp32 ======================================================
    cvt.f32.f16     %f_x, %h_in;

    //=== Constants ============================================================
    mov.f32         %c_044715,          0.044715;
    mov.f32         %c_sqrt_2_over_pi,  0.7978845608028654; // sqrt(2/pi)
    mov.f32         %c_half,            0.5;
    mov.f32         %c_one,             1.0;

    //=== x^3 ===================================================================
    mul.f32         %f_x3, %f_x, %f_x;
    mul.f32         %f_x3, %f_x3, %f_x;

    //=== inner = x + 0.044715 * x^3 ==========================================
    mul.f32         %f_inner, %f_x3, %c_044715;
    add.f32         %f_inner, %f_inner, %f_x;

    //=== tanh argument = sqrt(2/pi) * inner ==================================
    mul.f32         %f_tanh_arg, %f_inner, %c_sqrt_2_over_pi;

    //=== tanh approximation ====================================================
    tanh.approx.f32 %f_tanh, %f_tanh_arg;

    //=== GELU approx: 0.5 * x * (1 + tanh(arg)) ==============================
    add.f32         %f_tanh, %f_tanh, %c_one;   // 1 + tanh
    mul.f32         %f_y,    %f_x, %f_tanh;
    mul.f32         %f_y,    %f_y, %c_half;

    //=== Convert back to fp16 =================================================
    cvt.rn.f16.f32  %h_out, %f_y;

    //=== Store result =========================================================
    st.global.f16   [%addr_out], %h_out;

DONE:
    ret;
}
"""

class ModelNew:
    def __init__(self):
        # Load the PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "gelu_fp16"

    def __call__(self, x):
        """
        Executes the GELU kernel on the input tensor `x` (fp16 CUDA tensor)
        and returns a new tensor with the activation applied.
        """
        import torch

        if not x.is_cuda or x.dtype != torch.float16:
            raise TypeError("Input tensor must be a CUDA fp16 tensor")

        out = torch.empty_like(x)
        N = x.numel()

        # Launch configuration: 256 threads per block
        block = (256, 1, 1)
        grid = ((N + block[0] - 1) // block[0], 1, 1)

        # Arguments: input pointer, output pointer, element count (int64)
        args = [x.data_ptr(), out.data_ptr(), N]

        # Launch the kernel via the harness
        ptx_launch(self.module, self.kernel_name, grid, block, args)

        return out
